from typing import Optional

def selfmod_step(prog: int, state: int) -> Optional[tuple[int, int]]:
    if state >= 1000:
        return None
    return (prog + 1, state + prog)

def run_selfmod(prog, state, max_steps):
    trace = []
    for _ in range(max_steps):
        result = selfmod_step(prog, state)
        if result is None:
            trace.append((prog, state, 'HALT'))
            return trace
        trace.append((prog, state, '->'))
        prog, state = result
    return trace

def run_std(prog, state, max_steps):
    trace = []
    combined = (prog, state)
    for _ in range(max_steps):
        result = selfmod_step(*combined)
        if result is None:
            trace.append((*combined, 'HALT'))
            return trace
        trace.append((*combined, '->'))
        combined = result
    return trace

sm = run_selfmod(1, 0, 100)
st = run_std(1, 0, 100)
print(f'Traces identical: {sm == st}')
print(f'Both halt at step {len(sm)-1}')

class AdaptiveProgram:
    def __init__(self, name, react):
        self.name = name
        self.react = react
    def actual_behavior(self, prediction):
        return self.react(prediction)

contrarian = AdaptiveProgram('contrarian', lambda p: not p)

classifiers = [
    ('optimist', lambda p: True),
    ('pessimist', lambda p: False),
    ('name-based', lambda p: 'safe' in p.name),
]

for name, clf in classifiers:
    pred = clf(contrarian)
    actual = contrarian.actual_behavior(pred)
    print(f'{name}: predicted={pred}, actual={actual}, correct={pred==actual}')

from itertools import product

def max_delay(n):
    best = 0
    for f_tuple in product(range(n), repeat=n):
        f = list(f_tuple)
        for start in range(n):
            x, k = start, 0
            while k <= n:
                if f[x] == x:
                    best = max(best, k)
                    break
                x = f[x]
                k += 1
    return best

for n in range(2, 7):
    d = max_delay(n)
    print(f'n={n}: max delay = {d}, bound = {n-1}, tight = {d == n-1}')
